  retry.hidden = choice === 'right';
  if (choice === 'right') {
    solution.querySelector('strong').textContent = 'Right. Solution:';
    solution.hidden = false;
  }
  labels();
  (choice === 'right' ? solution : retry).scrollIntoView({ block: 'nearest', behavior: 'smooth' });
};
// opening a step sets the twin as the steps before it left it (`start`), once per visit, and says what it changed;
// the boxes show the changes until the twin follows them (box.js)
const LABELS = { hosts: 'Hosts', carbon_zone: 'CO₂ zone', calibration: 'Calibration', calibration_min: 'r from', calibration_max: 'r to' };
const shown = (value) => (value === true ? 'On' : value === false ? 'Off' : Number.isFinite(value) ? value.toLocaleString('en') : value);
if (context.grafana.replaceVariables('${step}') === step && sessionStorage.getItem('opendt-step') !== step) {
  sessionStorage.setItem('opendt-step', step);
  fetch(status).then((response) => response.json()).then(async (now) => {
    const change = Object.fromEntries(Object.entries(start).filter(([key, value]) => String(now[key]) !== String(value)));
    if (!Object.keys(change).length) return;
    const response = await fetch(control, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(change) });
    if (!response.ok) return context.grafana.notifyError(['OpenDT', 'Step ' + step + ' could not set the twin']);
    const pending = JSON.parse(sessionStorage.getItem('opendt-pending') || '{}');
    Object.entries(change).forEach(([key, value]) => (pending[key] = { value: String(value), at: Date.now() }));
    sessionStorage.setItem('opendt-pending', JSON.stringify(pending));
    const text = Object.entries(change).map(([key, value]) => LABELS[key] + ' ' + shown(value)).join(', ');
    context.grafana.notifySuccess(['OpenDT', 'Step ' + step + ' starts from ' + text]);
    context.grafana.refresh();
  });
}

options.styles:
.opendt-start { min-height: 70vh; width: 56%; margin: 0 auto; display: flex; flex-direction: column;
  justify-content: center; gap: 18px; }
.opendt-start .doing { font-size: 17px; text-transform: uppercase; letter-spacing: 0.04em;
  white-space: nowrap; }
.opendt-start .bar { aspect-ratio: 24 / 1; background: rgba(128, 128, 128, 0.2); border-radius: 999px; overflow: hidden; }
.opendt-start .bar div { width: 0; height: 100%; border-radius: 999px; transition: width 0.2s linear;
  background: linear-gradient(90deg, #1f5f86, #338ec1 70%, #6cc0ee); box-shadow: 0 0 18px rgba(51, 142, 193, 0.55); }
.opendt-start .tip { position: fixed; bottom: 12%; left: 0; right: 0; text-align: center; color: #8e8e9e;
  font-size: 17px; white-space: nowrap; }

options.afterRender:
const progress = "http://localhost:3001/api/progress";
// CSS for what lies outside the panel, added once to the page (the panel renders at every refresh), in the colours
// of Grafana's theme: var(--panel), var(--canvas), var(--line), and var(--ink)
const css = (id, text) => {
  const { background, border, text: ink } = context.grafana.theme.colors;
  const theme = ':root { --panel: ' + background.primary + '; --canvas: ' + background.canvas + '; --line: ' + border.medium + '; --ink: ' + ink.primary + ' }\n';
  document.getElementById(id) || document.head.insertAdjacentHTML('beforeend', '<style id="' + id + '">' + theme + text + '</style>');
};
// none of Grafana's own: no "Powered by Grafana" under the screen, no menus over the panels
const grafana = ['[data-testid="public-dashboard-footer"]', '[data-testid="hover-header-container"]', 'button[aria-label^="Menu for panel"]'];
css('opendt-grafana', grafana.join(', ') + ' { display: none !important; }');
// light or dark, as last chosen in this browser; Grafana takes its theme from the address, when the page loads
const light = document.body.classList.contains('theme-light');
const theme = (name) => {
  const address = new URL(location.href);
  address.searchParams.set('theme', name);
  location.replace(address);
};
const chosen = localStorage.getItem('opendt-theme');
if (chosen && (chosen === 'light') !== light) theme(chosen);
// the bar creeps toward the end of its step, so it never stands still; once the twin's first window is done, the
// page reloads to show the twin (the rows follow a variable read at load)
const state = (window.opendtStart ??= { step: 0, since: Date.now() });
const card = () => document.querySelector('.opendt-start');
const step = Number(card()?.dataset.step || 1);
if (step !== state.step) Object.assign(state, { step, since: Date.now() });
state.bar ??= setInterval(() => {
  const el = card();
  if (!el) return;
  const near = 1 - Math.exp(-(Date.now() - state.since) / 20000); // toward the end of the step, never at it
  el.querySelector('.bar div').style.width = (100 * (state.step - 1 + 0.9 * near)) / Number(el.dataset.steps) + '%';
}, 200);
state.ready ??= setInterval(async () => {
  try {
    const { data } = await (await fetch(progress)).json();
    if (!data.length) location.reload();
  } catch {} // the API is not up yet
}, 3000);
